// n8n Function Item
// Rebuild HTML from numeric-keyed object, then extract jobbkk links
// PDFs are sorted to the top

// turn the weird object into a string
const obj = $('Move to In process folder').first().json.body.content;
let html = '';

if (typeof obj === 'object' && !Array.isArray(obj)) {
  // numeric-keyed object -> join chars
  const keys = Object.keys(obj)
    .filter(k => /^\d+$/.test(k))
    .map(k => Number(k))
    .sort((a, b) => a - b);
  html = keys.map(k => obj[k]).join('');
} else if (Array.isArray(obj)) {
  html = obj.join('');
} else if (typeof obj === 'string') {
  html = obj;
}

// allowed prefixes
const prefixes = [
  "https://www.jobbkk.com/upload/jobseeker/00/000/000000/document",
  "https://jobbkk.com/upload/jobseeker/00/000/000000/document",
  "https://www.jobbkk.com/resumes/view/detail",
  "https://jobbkk.com/resumes/view/detail",
  "https://www.jobbkk.com/upload/jobseeker",
  "https://www.jobbkk.com/assets/template/jobbkk"
];

// find all links in HTML
const linkRegex = /https:\/\/(?:www\.)?jobbkk\.com\/[^\s"'<>]+/g;
const found = html.match(linkRegex) || [];

// keep only exact prefix matches
const filtered = found.filter(url =>
  prefixes.some(p => url.startsWith(p))
);

// remove duplicates
const unique = [...new Set(filtered)];

// sort so PDFs are on top
unique.sort((a, b) => {
  const aIsPdf = a.toLowerCase().endsWith('.pdf');
  const bIsPdf = b.toLowerCase().endsWith('.pdf');

  if (aIsPdf && !bIsPdf) return -1;
  if (!aIsPdf && bIsPdf) return 1;
  return a.localeCompare(b);
});

return {
  ...$json,
  jobbkk: unique
};

