// Get the array of sources (adjusting for nested structure)
const sources = $('Get source').all()[0].json.data.data;

// Get the sender email
const email = $('Get a message').first().json.sender.emailAddress.address;

// Helper to match email in source records
function findSourceIdByEmail(emailToFind) {
  if (!emailToFind) return null;

  const lower = emailToFind.toLowerCase();

  return sources.find(source => {
    if (!source.email) return false;

    // Support comma-separated emails
    return source.email
      .toLowerCase()
      .split(',')
      .map(e => e.trim())
      .includes(lower);
  })?.id || null;
}

// Get the matching source ID
const sourceId = findSourceIdByEmail(email);

// Return in n8n-compatible format
return [
  {
    json: {
      sourceId: sourceId
    }
  }
];

const output = [];

// Get jobs from the first input item
const jobs = items[0].json.data.data;

for (const job of jobs) {
  output.push({
