}

return output;

// Get the raw JSON string
let rawJson = $input.first().json.output

// Clean unwanted characters like triple backticks and markdown tags
rawJson = rawJson
  .replace(/```json\s*/g, '')  // Remove starting ```json
  .replace(/```/g, '')         // Remove closing ```
  .trim();                     // Remove extra whitespace

let parsed;

try {
  parsed = JSON.parse(rawJson);
} catch (error) {
  throw new Error("Failed to parse JSON: " + error.message);
}

// Return parsed JSON in n8n format
return [
  {
    json: parsed
  }
];

// n8n Code node — Single output, SINGLE item
// - Primary binary:   binary.primaryAttachement   (kept as-is per your flow)
// - Additionals:      binary.additionalAttachment_1 ... _N  (suffix only)

// -------- helpers to read other nodes --------
function safeAll(nodeName) {
  try { const items = $(nodeName).all(); return Array.isArray(items) ? items : []; }
  catch { return []; }
}
function collectAllAttachments(nodeName) {
  const items = safeAll(nodeName);
  const files = [];
  for (let idx = 0; idx < items.length; idx++) {
    const it = items[idx];
    if (!it || !it.binary) continue;
    for (const key of Object.keys(it.binary)) {
      files.push({
        json: { __sourceNode: nodeName, __sourceItem: idx, __binaryKey: key },
        binary: { [key]: it.binary[key] },
      });
    }
  }
  return files;
}
function getKeyAndFile(attItem) {
  const keys = attItem?.binary ? Object.keys(attItem.binary) : [];
  const k = keys[0];
  const f = k ? attItem.binary[k] : null;
  return [k, f];
}
function nameOf(attItem) {
  const [k, f] = getKeyAndFile(attItem);
  return ((f && f.fileName) || k || '').toLowerCase();
}
function fileMeta(attItem) {
  const [k, f] = getKeyAndFile(attItem);
  return {
    key: k || '',
    name: (f && f.fileName) || k || '',
    mimeType: (f && f.mimeType) || '',
    fileSize: (f && f.fileSize) !== undefined ? f.fileSize : undefined,
    sourceNode: attItem.json.__sourceNode,
    sourceItem: attItem.json.__sourceItem,
  };
}

// -------- type checks --------
function isPdf(file){
  if (!file) return false;
  const mt = (file.mimeType || '').toLowerCase();
  const fn = (file.fileName || '').toLowerCase();
  return mt === 'application/pdf' || fn.endsWith('.pdf');
}
function isWord(file){
  if (!file) return false;
  const mt = (file.mimeType || '').toLowerCase();
  const fn = (file.fileName || '').toLowerCase();
  return mt === 'application/msword' ||
         mt === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' ||
         fn.endsWith('.doc') || fn.endsWith('.docx');
}
function isImage(file){
  if (!file) return false;
  const mt = (file.mimeType || '').toLowerCase();
  const fn = (file.fileName || '').toLowerCase();
  return mt.startsWith('image/') || /\.(png|jpe?g|webp|gif|bmp|tiff?|heic)$/.test(fn);
}

// -------- keyword priority (highest → lowest) --------
const keywordMatchers = [
  { label: 'resume',    test: (n) => /resume/i.test(n) },
  { label: 'cv',        test: (n) => /(^|[^a-z0-9])c[\s._-]*v([^a-z0-9]|$)/i.test(n) },
  { label: 'profile',   test: (n) => /(profile|prolfile)/i.test(n) },
  { label: 'ประวัติ',    test: (n) => n.includes('ประวัติ') },
  { label: 'portfolio', test: (n) => /portfolio/i.test(n) },
  { label: 'ใบสมัคร',    test: (n) => n.includes('ใบสมัคร') },
];

function choosePrimaryIndex(attachments){
  if (!attachments || attachments.length === 0) return { index: -1, reason: 'no-attachments' };

  // 1) keywords first
  for (const m of keywordMatchers) {
    for (let i = 0; i < attachments.length; i++) {
      if (m.test(nameOf(attachments[i]))) return { index: i, reason: `keyword:${m.label}` };
    }
  }
  // 2) type fallback
  const groups = [
    { label: 'pdf',   pred: (f) => isPdf(f) },
    { label: 'word',  pred: (f) => isWord(f) },
    { label: 'image', pred: (f) => isImage(f) },
  ];
  for (const g of groups) {
    for (let i = 0; i < attachments.length; i++) {
      const [, f] = getKeyAndFile(attachments[i]);
      if (g.pred(f)) return { index: i, reason: `type:${g.label}` };
    }
  }
  // 3) first file
  return { index: 0, reason: 'fallback:first' };
}

// -------- MAIN --------
const attachments = [
  ...collectAllAttachments('get inprogress id'),
  ...collectAllAttachments('Convert to File'),
  ...collectAllAttachments('Switch of file'),
  ...collectAllAttachments('download PDF from link')
];

// Always return ONE item
if (attachments.length === 0) {
  return [{
    json: {
      role: 'none',
      primary: { key: '', name: '', mimeType: '', fileSize: undefined, sourceNode: '', sourceItem: undefined, reason: 'no-attachments' },
      additionalKeys: [],
      additionalNames: [],
      additionalCount: 0,
      totalFound: 0,
      attachments: [],
    },
    binary: {},
  }];
}

const { index: primaryIdx, reason } = choosePrimaryIndex(attachments);
const primary = attachments[primaryIdx];
const others  = attachments.filter((_, i) => i !== primaryIdx);

const [pKey, pFile] = getKeyAndFile(primary);

// Binary container (single item)
const binaryOut = {};
if (pFile) binaryOut.primaryAttachement = pFile;

// Add ALL additionals with suffixed keys only
const additionalKeys = [];
const additionalNames = [];
others.forEach((it, i) => {
  const [k, f] = getKeyAndFile(it);
  const idx = i + 1;
  const binKey = `additionalAttachment_${idx}`;
  if (f) {
    binaryOut[binKey] = f;
    additionalKeys.push(binKey);
    additionalNames.push(f.fileName || k || '');
  }
});

const outItem0 = {
  json: {
    role: 'primary',
    primary: { ...fileMeta(primary), reason },
    primaryFileKey: pKey || null,
    primaryFileName: (pFile && pFile.fileName) || pKey || '',
    primaryFileReason: reason,
    additionalKeys,               // e.g. ["additionalAttachment_1", "additionalAttachment_2"]
    additionalNames,              // names in the same order
    additionalCount: others.length,
    totalFound: attachments.length,
    attachments: attachments.map((att, idx) => ({ ...fileMeta(att), isPrimary: idx === primaryIdx })),
  },
  binary: binaryOut,
};

return [outItem0];

// Input: items[0].json.html (or adjust to your field)
const html = $('Move to In process folder').first().json.body.content || "";

// Function to clean HTML completely
function cleanHtml(html) {
  return html
    // remove CSS <style>...</style>
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, "")
    // remove all HTML comments
    .replace(/<!--[\s\S]*?-->/g, "")
    // remove all HTML tags
    .replace(/<[^>]+>/g, " ")
    // decode common HTML entities
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    // cleanup extra spaces
    .replace(/\s+/g, " ")
    .trim();
}

return [
  {
    json: {
      text: cleanHtml(html)
    }
  }
];
